test('saved record self selection persists without changing scores or record identity',async()=>{const a=await app();await save(a);const context=a.bridge.context(),record=context.records[0];a.bridge.assignSelf(record.id,'a',context);const updated=a.bridge.context().records[0];assert.equal(updated.id,record.id);assert.equal(updated.createdAt,record.createdAt);assert.equal(updated.players.find(p=>p.isSelf).id,'a');assert.deepEqual(updated.players.map(p=>p.score),record.players.map(p=>p.score));const restored=await app(a.store);assert.equal(restored.bridge.context().records[0].players.find(p=>p.isSelf).id,'a');});
test('self selection rejects a stale account or an invalid player before changing records',async()=>{const a=await app();await save(a);const context=a.bridge.context(),record=context.records[0];assert.throws(()=>a.bridge.assignSelf(record.id,'a',{...context,epoch:context.epoch+1}),/계정/);assert.throws(()=>a.bridge.assignSelf(record.id,'missing',context),/플레이어/);assert.equal(a.bridge.context().records[0].players.some(p=>p.isSelf),false);});
test('history omits analysis and shows personal record labels only on qualifying cards',async()=>{const a=await app(),make=(id,date,score)=>({id,date,createdAt:date+'T12:00:00Z',game:{name:'카탄',bggId:'13'},rule:'highest',players:[{id:'a',name:'나',score,color:'#52c7ef',isSelf:true},{id:'b',name:'친구',score:5,color:'#ffcc00',isSelf:false}]});a.bridge.merge([make('first','2026-01-01',10),make('new','2026-01-02',12),make('tie','2026-01-03',12)],a.bridge.context());a.get('statsAll').onclick();const cards=a.get('recordList').children;const find=(e,cls)=>e.className===cls||e.children.some(c=>find(c,cls));assert.equal(cards.filter(c=>find(c,'record-best-badge')).length,1);assert.equal(cards.find(c=>find(c,'record-best-badge')).id,'record-new');assert.equal(cards.some(c=>find(c,'record-analysis')),false);});
test('record name and score buttons open compact editor and persist changes without touching the live board',async()=>{const a=await app();await save(a);const before=JSON.stringify(a.players()),id=a.bridge.context().records[0].id;let row=a.get('recordList').children[0].children[2].children[0];row.children[0].onclick();assert.equal(a.get('recordEditDialog').open,true);a.get('recordEditValue').value='새 이름';a.get('recordEditForm').onsubmit({preventDefault(){}});assert.equal(a.bridge.context().records[0].players[0].name,'새 이름');row=a.get('recordList').children[0].children[2].children[0];row.children[1].onclick();a.get('recordEditValue').value='-4.5';a.get('recordEditForm').onsubmit({preventDefault(){}});assert.equal(a.bridge.context().records[0].players[0].score,-4.5);assert.equal(JSON.stringify(a.players()),before);const reload=await app(a.store);assert.equal(reload.bridge.context().records[0].id,id);assert.equal(reload.bridge.context().records[0].players[0].score,-4.5);});
test('scoreless record rows show main-board wins and losses and allow later result edits',async()=>{const a=await app();await beginScoreless(a);assert.equal(a.get('scorelessBoardPanel').hidden,false);a.players()[0].winner=true;a.players()[1].winner=false;await finishScoreless(a);let rows=a.get('recordList').children[0].children[2].children;assert.equal(rows[0].children[2].textContent,'승리');assert.equal(rows[1].children[2].textContent,'패배');rows[0].children[2].onclick();assert.equal(a.get('recordEditValue').hidden,true);assert.equal(a.get('recordEditResult').hidden,false);assert.equal(a.get('recordEditResult').children.length,6);a.get('recordEditResult').value='rank:1';a.get('recordEditForm').onsubmit({preventDefault(){}});assert.equal(a.bridge.context().records[0].players[0].rank,1);assert.equal(a.bridge.context().records[0].players[0].winner,true);rows=a.get('recordList').children[0].children[2].children;assert.equal(rows[0].children[2].textContent,'1위');const reload=await app(a.store);assert.equal(reload.bridge.context().records[0].players[0].rank,1);assert.equal(reload.bridge.context().records[0].players[1].winner,false);});
test('record deletion persists and stale account editors cannot edit or delete another account',async()=>{const a=await app();await save(a);const context=a.bridge.context();a.bridge.deletePlay(context.records[0].id,context);assert.equal(a.bridge.context().records.length,0);assert.equal((await app(a.store)).bridge.context().records.length,0);const auth=await app(new Map(),true);await auth.changeAuth({uid:'one'});await save(auth);const stale=auth.bridge.context();await auth.changeAuth({uid:'two'});assert.throws(()=>auth.bridge.deletePlay(stale.records[0].id,stale),/계정이 변경/);assert.throws(()=>auth.bridge.updatePlayer(stale.records[0].id,'a','score','1',stale),/계정이 변경/);});
test('delete during a manual in-flight cloud save runs after save and remains queued after an offline failure',async()=>{const source=`export const cloudConfigured=()=>true;export async function connectCloud(cb){globalThis.changeAuth=cb;}export async function login(){}export async function logout(){}export async function loadCloud(){return [];}export async function saveCloud(){globalThis.ops.push('save');await new Promise(resolve=>globalThis.releaseSave=resolve);}export async function deleteCloud(){globalThis.ops.push('delete');if(globalThis.failDelete)throw Error('offline');}export async function idToken(){return '';}`;const a=await app(new Map(),true,source);a.vm.ops=[];a.vm.failDelete=true;await a.changeAuth({uid:'one'});await save(a);const syncing=a.get('cloudSync').onclick();await new Promise(r=>setTimeout(r,0));const context=a.bridge.context();a.bridge.deletePlay(context.records[0].id,context);a.vm.releaseSave();await syncing;assert.equal(a.vm.ops.join(','),'save,delete');assert.equal(a.bridge.context().records.length,0);assert.ok(JSON.parse(a.store.get('score.plays.v1.user.one')).pending.includes(context.records[0].id));const b=await app(a.store,true,source);b.vm.ops=[];b.vm.failDelete=false;await b.changeAuth({uid:'one'});assert.equal(b.vm.ops.length,0);await b.get('cloudSync').onclick();assert.equal(b.vm.ops.join(','),'delete');assert.equal(JSON.parse(b.store.get('score.plays.v1.user.one')).pending.length,0);});
test('record player deletion persists without deleting the game or changing the live board and rejects stale accounts',async()=>{const a=await app();await save(a);const before=JSON.stringify(a.players()),context=a.bridge.context(),id=context.records[0].id;const row=a.get('recordList').children[0].children[2].children[0];row.children[0].onclick();assert.equal(a.get('recordDeletePlayer').hidden,false);a.get('recordDeletePlayer').onclick();assert.equal(a.get('recordEditDialog').open,false);assert.equal(a.bridge.context().records[0].players.length,1);assert.equal(JSON.stringify(a.players()),before);assert.equal((await app(a.store)).bridge.context().records[0].players.length,1);assert.throws(()=>a.bridge.deletePlayer(id,'b',a.bridge.context()),/마지막 플레이어/);assert.throws(()=>a.bridge.deletePlayer(id,'b',{...context,epoch:999}),/계정이 변경/);});
test('setup selects game then player count before creating a live board, without saving a finished play',async()=>{const a=await app();a.vm.window.ScoreCounter.restorePlayers([]);a.bridge.openSave();assert.equal(a.get('savePlayDialog').open,true);assert.equal(a.get('commitPlay').textContent,'플레이어 추가');assert.equal(a.get('playSnapshot').hidden,true);a.get('playGame').value='카탄';a.get('playDate').value='2026-10-15';a.get('playRule').value='highest';await a.get('savePlayForm').onsubmit({preventDefault(){}});assert.equal(a.get('gamePlayersDialog').open,true);assert.equal(a.players().length,0);a.get('gamePlayerCount').value='3';a.get('gamePlayersForm').onsubmit({preventDefault(){}});assert.equal(a.players().length,3);assert.ok(a.players().every(p=>p.score===0));assert.equal(a.bridge.context().records.length,0);assert.match(a.get('recordingStatus').textContent,/카탄 점수 기록을 시작했습니다/);assert.equal(a.vm.location.hash,'home');});
test('saving without scores preserves live points and never invents a winner',async()=>{const a=await app();a.bridge.openFinish();a.get('playGame').value='협동 게임';a.get('playWithoutScores').checked=true;await a.get('savePlayForm').onsubmit({preventDefault(){}});assert.ok(a.bridge.context().records[0].players.every(p=>p.score===null));assert.equal(a.players()[0].score,20);});
test('login from recording preserves the draft and saves it into the selected account',async()=>{const source=`export const cloudConfigured=()=>true;export async function connectCloud(cb){globalThis.changeAuth=cb;}export async function login(){await globalThis.changeAuth({uid:'draft-account'});}export async function logout(){}export async function loadCloud(){return [];}export async function saveCloud(){}export async function deleteCloud(){}export async function idToken(){return '';}`;const a=await app(new Map(),true,source);a.bridge.openFinish();a.get('playGame').value='로그인 도중 유지';a.get('playDate').value='2026-10-15';await a.get('recordLogin').onclick();assert.ok(a.bridge.context().key.endsWith('.draft-account'));assert.equal(a.bridge.context().records[0].game.name,'로그인 도중 유지');assert.equal(a.get('savePlayDialog').open,false);});
const syncMock=`export const cloudConfigured=()=>true;export async function connectCloud(cb){globalThis.changeAuth=cb;}export async function login(){}export async function logout(){}export async function loadCloud(uid){if(globalThis.readError)throw Object.assign(Error('denied'),{code:'permission-denied'});return globalThis.remote||[];}export async function saveCloud(play,uid){if(globalThis.writeError)throw Error('offline');globalThis.uploads.push({uid,play});}export async function deleteCloud(){}export async function idToken(){return '';}`;
const storedPlay={id:'existing',game:{name:'카탄',bggId:'13'},date:'2026-10-15',createdAt:'2026-10-15T12:00:00Z',rule:'highest',players:[{id:'a',name:'나',score:20,color:'#52c7ef'}]};
test('login waits for the cloud sync CTA before loading account records',async()=>{const a=await app(new Map(),true,syncMock);a.vm.remote=[storedPlay];a.vm.uploads=[];await a.changeAuth({uid:'same'});assert.equal(a.bridge.context().records.length,0);assert.match(a.get('accountStorage').textContent,/클라우드 동기화를 눌러/);await a.get('cloudSync').onclick();assert.equal(a.bridge.context().records.length,1);assert.match(a.get('accountStorage').textContent,/동기화됨.*1개/);assert.equal(a.vm.uploads.length,0);});
test('manual failed reads retain local games and show a persistent account error',async()=>{const store=new Map([['score.plays.v1.user.same',JSON.stringify({records:[storedPlay],pending:[]})]]);const a=await app(store,true,syncMock);a.vm.readError=true;a.vm.uploads=[];await a.changeAuth({uid:'same'});assert.equal(a.get('accountError').textContent,'');await a.get('cloudSync').onclick();assert.equal(a.bridge.context().records.length,1);assert.match(a.get('accountError').textContent,/접근 권한/);assert.match(a.get('accountStorage').textContent,/실패/);});
test('manual sync backs up remote removals and restores only into the owning account',async()=>{const store=new Map([['score.plays.v1.user.same',JSON.stringify({records:[storedPlay],pending:[]})]]);const a=await app(store,true,syncMock);a.vm.uploads=[];await a.changeAuth({uid:'same'});assert.equal(a.bridge.context().records.length,1);await a.get('cloudSync').onclick();assert.equal(a.bridge.context().records.length,0);assert.equal(a.vm.uploads.length,0);assert.equal(a.get('recoverRecords').hidden,false);assert.equal(JSON.parse(store.get('score.plays.v1.user.same.recovery')).records[0].id,'existing');a.get('recoverRecords').onclick();await new Promise(r=>setTimeout(r,0));assert.equal(a.bridge.context().records.length,1);assert.equal(a.vm.uploads[0].uid,'same');await a.changeAuth({uid:'other'});assert.equal(a.get('recoverRecords').hidden,true);});
test('manual sync never lets malformed cloud records erase valid local records',async()=>{const store=new Map([['score.plays.v1.user.same',JSON.stringify({records:[storedPlay],pending:[]})]]);const a=await app(store,true,syncMock);a.vm.remote=[{id:'bad'}];a.vm.uploads=[];await a.changeAuth({uid:'same'});await a.get('cloudSync').onclick();assert.equal(a.bridge.context().records.length,1);assert.match(a.get('accountError').textContent,/形式|형식/);});
test('local writes wait for manual sync and failed uploads remain pending',async()=>{const a=await app(new Map(),true,syncMock);a.vm.uploads=[];await a.changeAuth({uid:'same'});a.vm.writeError=true;await save(a);assert.equal(a.vm.uploads.length,0);assert.equal(JSON.parse(a.store.get('score.plays.v1.user.same')).pending.length,1);assert.match(a.get('accountStorage').textContent,/동기화 대기/);await a.get('cloudSync').onclick();assert.equal(JSON.parse(a.store.get('score.plays.v1.user.same')).pending.length,1);assert.match(a.get('accountStorage').textContent,/실패/);assert.match(a.get('accountError').textContent,/offline/);});
test('manual sync remains account-scoped while an earlier account upload is blocked',async()=>{const source=syncMock.replace("if(globalThis.writeError)throw Error('offline');globalThis.uploads.push({uid,play});","globalThis.uploads.push({uid,play});if(uid==='one')await new Promise(resolve=>globalThis.releaseOne=resolve);");const store=new Map([['score.plays.v1.user.two',JSON.stringify({records:[storedPlay],pending:['existing']})]]);const a=await app(store,true,source);a.vm.uploads=[];await a.changeAuth({uid:'one'});await save(a);const firstSync=a.get('cloudSync').onclick();await new Promise(r=>setTimeout(r,0));await a.changeAuth({uid:'two'});await a.get('cloudSync').onclick();assert.ok(a.vm.uploads.some(p=>p.uid==='two'));assert.equal(JSON.parse(store.get('score.plays.v1.user.two')).pending.length,0);a.vm.releaseOne();await firstSync;assert.equal(a.bridge.context().records[0].id,'existing');});

test('manual loading and saving show progress and clear on completion or failure',async()=>{const source=syncMock.replace('return globalThis.remote||[];',"if(globalThis.blockRead)await new Promise(resolve=>globalThis.releaseRead=resolve);return globalThis.remote||[];").replace("if(globalThis.writeError)throw Error('offline');", "if(globalThis.blockWrite)await new Promise(resolve=>globalThis.releaseWrite=resolve);if(globalThis.writeError)throw Error('offline');");const a=await app(new Map(),true,source);a.vm.uploads=[];a.vm.blockRead=true;await a.changeAuth({uid:'same'});assert.equal(a.get('cloudProgress').hidden,true);const read=a.get('cloudSync').onclick();await new Promise(r=>setTimeout(r,0));assert.equal(a.get('cloudProgress').hidden,false);assert.match(a.get('cloudProgress').textContent,/불러오는/);assert.equal(a.get('cloudSync').disabled,true);assert.equal(a.get('cloudSync').attributes['aria-busy'],'true');a.vm.releaseRead();await read;assert.equal(a.get('cloudProgress').hidden,true);assert.equal(a.get('cloudSync').disabled,false);a.vm.blockRead=false;a.vm.blockWrite=true;a.vm.writeError=true;await save(a);assert.equal(a.get('cloudProgress').hidden,true);const write=a.get('cloudSync').onclick();for(let i=0;i<5&&typeof a.vm.releaseWrite!=='function';i++)await new Promise(r=>setTimeout(r,0));assert.equal(a.get('cloudProgress').hidden,false);assert.match(a.get('cloudProgress').textContent,/동기화/);a.vm.releaseWrite();await write;assert.equal(a.get('cloudProgress').hidden,true);assert.equal(a.get('cloudSync').attributes['aria-busy'],'false');assert.equal(a.get('cloudSync').disabled,false);});

test('auth restoration hides signed-out settings controls until the first verified auth result',async()=>{const a=await app(new Map(),true);assert.equal(a.get('authChecking').hidden,false);assert.equal(a.get('accountLogin').hidden,true);assert.equal(a.get('accountName').hidden,true);await a.changeAuth({uid:'restored',displayName:'복원 계정'});assert.equal(a.get('authChecking').hidden,true);assert.equal(a.get('accountLogin').hidden,true);assert.equal(a.get('accountName').textContent,'복원 계정');await a.changeAuth(null);assert.equal(a.get('accountLogin').hidden,false);assert.equal(a.get('accountName').hidden,false);});
test('auth initialization failure ends the loading state and permits retry',async()=>{const source=syncMock.replace('globalThis.changeAuth=cb;',"throw Error('connection failed');");const a=await app(new Map(),true,source);await new Promise(r=>setTimeout(r,0));assert.equal(a.get('authChecking').hidden,true);assert.equal(a.get('accountLogin').hidden,false);assert.match(a.get('accountError').textContent,/로그인 상태.*확인하지 못/);});

