test('Score native game search stays local and stores no BGG ID',async()=>{let called=false;const a=await app(new Map(),false,'',{endpoint:'https://worker.example',fetch:async()=>{called=true;throw Error('must stay local');}});await beginScoreless(a,'테니스','2','win');a.players()[0].winner=true;a.players()[1].winner=false;a.get('savePlay').onclick();a.get('playGame').value='테니스';a.get('playGame').listeners.input();assert.equal(a.get('bggResults').children[0].children[0].children[1].children[0].textContent,'테니스');assert.equal(a.get('openBggWebsite').hidden,true);await a.get('searchBgg').onclick();assert.equal(called,false);a.get('bggResults').children[0].children[0].onclick();assert.equal(a.get('playBggId').value,'');a.get('playDate').value='2026-10-16';await a.get('savePlayForm').onsubmit({preventDefault(){}});assert.equal(a.bridge.context().records[0].game.bggId,'');});
